using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using BrewNest.Contracts.Catalog;
using BrewNest.Contracts.Identity;
using BrewNest.Contracts.Inventory;
using BrewNest.Contracts.Production;
using BrewNest.Modules.Catalog.Infrastructure.Persistence;
using BrewNest.Modules.Inventory.Infrastructure.Persistence;
using BrewNest.Modules.Production.Infrastructure.Persistence;
using Microsoft.Extensions.DependencyInjection;
namespace BrewNest.IntegrationTests;
/// <summary>Exercises Production authorization and its Catalog/Inventory contract workflow.</summary>
public sealed class ProductionEndpointTests:IClassFixture<IdentityWebApplicationFactory>,IAsyncLifetime
{
    private readonly IdentityWebApplicationFactory factory;
    /// <summary>Creates the Production suite.</summary>
    public ProductionEndpointTests(IdentityWebApplicationFactory factory)=>this.factory=factory;
    /// <inheritdoc />
    public async Task InitializeAsync(){await using var scope=factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<CatalogDbContext>().Database.EnsureCreatedAsync();await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Database.EnsureCreatedAsync();await scope.ServiceProvider.GetRequiredService<ProductionDbContext>().Database.EnsureCreatedAsync();}
    /// <inheritdoc />
    public Task DisposeAsync()=>Task.CompletedTask;
    /// <summary>Production endpoints require explicit permissions.</summary>
    [Fact]public async Task ProductionRequiresExplicitPermission(){using var client=Client();using var anonymous=await client.GetAsync("/api/production/plans");Assert.Equal(HttpStatusCode.Unauthorized,anonymous.StatusCode);var admin=await LoginAdmin(client);Bearer(client,admin.AccessToken);var email=$"production-denied-{Guid.NewGuid():N}@test.local";var password=IdentityWebApplicationFactory.CreateValidPassword();using var created=await client.PostAsJsonAsync("/api/identity/users",new CreateUserRequest(email,"Production Denied",password,[]));Assert.Equal(HttpStatusCode.OK,created.StatusCode);client.DefaultRequestHeaders.Authorization=null;using var login=await client.PostAsJsonAsync("/api/identity/auth/login",new LoginRequest(email,password));var token=Assert.IsType<TokenResponse>(await login.Content.ReadFromJsonAsync<TokenResponse>());Bearer(client,token.AccessToken);using var forbidden=await client.GetAsync("/api/production/plans");Assert.Equal(HttpStatusCode.Forbidden,forbidden.StatusCode);}
    /// <summary>A full plan-to-completion flow reserves, issues, records wastage, and calculates variance.</summary>
    [Fact]public async Task ProductionFlowReservesIssuesAndCompletes(){using var client=await AdminClient();var setup=await Setup(client,10m);var names=await client.GetFromJsonAsync<ProductionCatalogItemReference[]>("/api/production/item-names");Assert.Contains(names!,x=>x.Id==setup.Ingredient.Id&&x.Name=="Production ingredient");var plan=await Post<ProductionPlanResponse>(client,"/api/production/plans",new CreateProductionPlanRequest("Morning batch",DateOnly.FromDateTime(DateTime.UtcNow),"test",[new(setup.Menu.Id,10m)]));plan=await Post<ProductionPlanResponse>(client,$"/api/production/plans/{plan.Id}/release",new ChangeProductionStatusRequest("approved",plan.Version));Assert.Equal(ProductionPlanStatus.Released,plan.Status);var orders=await client.GetFromJsonAsync<ProductionOrderResponse[]>($"/api/production/orders?planId={plan.Id}");var order=Assert.Single(orders!);var requirement=Assert.Single(order.Requirements);Assert.Equal(2.1m,requirement.RequiredQuantity);order=await Post<ProductionOrderResponse>(client,$"/api/production/orders/{order.Id}/release",new ChangeProductionStatusRequest("reserve",order.Version));Assert.Equal(ProductionOrderStatus.Released,order.Status);order=await Post<ProductionOrderResponse>(client,$"/api/production/orders/{order.Id}/issue",new IssueProductionMaterialsRequest([new(setup.Ingredient.Id,2.2m,0.2m)],"actual issue",order.Version));Assert.Equal(0.3m,Assert.Single(order.Requirements).Variance);order=await Post<ProductionOrderResponse>(client,$"/api/production/orders/{order.Id}/complete",new ChangeProductionStatusRequest("completed",order.Version));Assert.Equal(ProductionOrderStatus.Completed,order.Status);plan=await client.GetFromJsonAsync<ProductionPlanResponse>($"/api/production/plans/{plan.Id}")??throw new InvalidOperationException();Assert.Equal(ProductionPlanStatus.Completed,plan.Status);var lots=await client.GetFromJsonAsync<StockLotResponse[]>($"/api/inventory/lots?itemId={setup.Ingredient.Id}");Assert.Equal(7.6m,Assert.Single(lots!).OnHandQuantity);}
    /// <summary>Insufficient Inventory blocks release and cancelling a released order restores availability.</summary>
    [Fact]public async Task ReleaseAndCancellationPreserveInventoryRules(){using var client=await AdminClient();var setup=await Setup(client,1m);var order=await CreateOrder(client,setup.Menu.Id,10m);using var insufficient=await client.PostAsJsonAsync($"/api/production/orders/{order.Id}/release",new ChangeProductionStatusRequest("reserve",order.Version));Assert.Equal(HttpStatusCode.Conflict,insufficient.StatusCode);setup=await Setup(client,10m);order=await CreateOrder(client,setup.Menu.Id,5m);order=await Post<ProductionOrderResponse>(client,$"/api/production/orders/{order.Id}/release",new ChangeProductionStatusRequest("reserve",order.Version));var lots=await client.GetFromJsonAsync<StockLotResponse[]>($"/api/inventory/lots?itemId={setup.Ingredient.Id}");Assert.True(Assert.Single(lots!).ReservedQuantity>0);order=await Post<ProductionOrderResponse>(client,$"/api/production/orders/{order.Id}/cancel",new ChangeProductionStatusRequest("cancel",order.Version));lots=await client.GetFromJsonAsync<StockLotResponse[]>($"/api/inventory/lots?itemId={setup.Ingredient.Id}");Assert.Equal(0m,Assert.Single(lots!).ReservedQuantity);}
    private static async Task<ProductionOrderResponse> CreateOrder(HttpClient client,Guid menuId,decimal quantity){var plan=await Post<ProductionPlanResponse>(client,"/api/production/plans",new CreateProductionPlanRequest("Plan",DateOnly.FromDateTime(DateTime.UtcNow),"",[new(menuId,quantity)]));await Post<ProductionPlanResponse>(client,$"/api/production/plans/{plan.Id}/release",new ChangeProductionStatusRequest("release",plan.Version));return Assert.Single((await client.GetFromJsonAsync<ProductionOrderResponse[]>($"/api/production/orders?planId={plan.Id}"))!);}
    private static async Task<SetupData> Setup(HttpClient client,decimal stock){var suffix=Guid.NewGuid().ToString("N")[..8];var unit=await Post<UnitOfMeasureResponse>(client,"/api/catalog/units",new CreateUnitOfMeasureRequest($"pu-{suffix}","Production unit","kg","Weight",3));var ingredient=await Post<CatalogItemResponse>(client,"/api/catalog/items",new CreateCatalogItemRequest($"pi-{suffix}","Production ingredient","","RawMaterial",unit.Id,null,null,100m,365,false));var menu=await Post<CatalogItemResponse>(client,"/api/catalog/items",new CreateCatalogItemRequest($"pm-{suffix}","Production output","","MenuItem",unit.Id,null,500m,100m,null,false));var warehouse=await Post<WarehouseResponse>(client,"/api/catalog/warehouses",new CreateWarehouseRequest($"pw-{suffix}","Production warehouse","Test"));await Post<RecipeResponse>(client,"/api/catalog/recipes",new CreateRecipeRequest($"pr-{suffix}","Production recipe",menu.Id,1m,unit.Id,[new(ingredient.Id,0.2m,5m,1)]));await Post<StockLotResponse>(client,"/api/inventory/receipts",new GoodsReceiptRequest(ingredient.Id,warehouse.Id,$"PLOT-{suffix}",DateOnly.FromDateTime(DateTime.UtcNow.AddDays(-1)),DateOnly.FromDateTime(DateTime.UtcNow.AddYears(1)),stock,"Test",suffix,"Production test stock"));return new(menu,ingredient);}
    private HttpClient Client()=>factory.CreateClient(new(){BaseAddress=new Uri("https://localhost")});private async Task<HttpClient> AdminClient(){var c=Client();var t=await LoginAdmin(c);Bearer(c,t.AccessToken);return c;}private async Task<TokenResponse> LoginAdmin(HttpClient c){c.DefaultRequestHeaders.Authorization=null;using var r=await c.PostAsJsonAsync("/api/identity/auth/login",new LoginRequest(factory.AdministratorEmail,factory.AdministratorPassword));Assert.Equal(HttpStatusCode.OK,r.StatusCode);return Assert.IsType<TokenResponse>(await r.Content.ReadFromJsonAsync<TokenResponse>());}private static void Bearer(HttpClient c,string token)=>c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);private static async Task<T> Post<T>(HttpClient c,string uri,object value){using var r=await c.PostAsJsonAsync(uri,value);Assert.Equal(HttpStatusCode.OK,r.StatusCode);return Assert.IsType<T>(await r.Content.ReadFromJsonAsync<T>());}private sealed record SetupData(CatalogItemResponse Menu,CatalogItemResponse Ingredient);
}
